// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "How would you compute the delivery promise shown at checkout, and how do you keep it honest?", "The promise service takes the cart items, the delivery pincode and the current time. For each item it finds the nodes holding sellable stock. For each candidate node it adds processing time, the next outbound cutoff, linehaul transit and last-mile capacity at the destination delivery station. The earliest feasible date with spare capacity becomes the promise. To keep it honest, the date is computed from the same inventory and capacity data that fulfilment later uses. The checkout response carries a short-lived promise token, and order creation re-validates it, so a promise that has expired is recomputed and shown again before the customer confirms. I would track promise-kept rate as an input metric and pad the estimate only when data shows systematic misses."),
    s(5, "How do you stop two customers from buying the last unit at the same time?", "Inventory is reserved, not just read. The reserve call does a conditional update on the SKU and node row: decrement available by the quantity only if available is at least that quantity, using a version check or a single atomic conditional write. Exactly one of the two concurrent requests succeeds. The other gets an out-of-stock result and can try another node or tell the customer. Reads for browsing and the product page can be eventually consistent and cached, because they only inform. The authoritative decision happens at the reservation write. For hot items in a flash sale, I would split a SKU's stock into several buckets so writes spread across partitions, and fall back to other buckets when one runs out."),
    s(5, "Why authorise at order time but capture at ship time, and how does that work with split shipments?", "Authorisation confirms the customer can pay and holds the funds without moving money. Amazon has publicly said it charges when the item ships, so the customer is not charged for something that might be cancelled or go out of stock before dispatch. With split shipments, each shipment's ship event triggers a capture for that shipment's amount, including its share of tax and discounts. The payment service must support multiple partial captures against one authorisation, or else re-authorise per shipment. Holds can expire if a shipment is delayed, so the system tracks hold validity and re-authorises before capture when needed. Each capture uses a key such as shipment ID plus attempt, so a retried ship event never charges twice."),
    s(5, "The payment gateway times out during authorisation. How do you avoid a double charge?", "A timeout means the outcome is unknown, not that it failed. Every authorisation request carries an idempotency key tied to the checkout attempt, and the gateway is asked to deduplicate on that key. On timeout I do not blindly retry with a new key. I mark the payment as pending, query the gateway's status API with the same key, and retry with the same key only if the gateway supports idempotent retries. Customer-side double clicks hit the same order idempotency key, so they return the existing order. A reconciliation job compares our ledger with gateway settlement files and automatically voids any orphan authorisations. The customer sees 'payment processing' rather than an error that tempts them to pay again."),
    s(4, "How do you make sure the order is saved and the order-created event is published, without losing one or the other?", "I use the transactional outbox pattern. In one local database transaction, the order service writes the order rows and an outbox row describing the event. A separate relay reads the outbox, or uses change data capture, and publishes to the event stream. It marks rows sent only after the broker acknowledges them. If the relay crashes, it republishes, so delivery is at-least-once. Every event carries the order ID and a sequence number, and consumers deduplicate on the event ID. This avoids a two-phase commit across the database and the broker. It also guarantees that downstream systems, such as inventory, fulfilment and notifications, never see an event for an order that does not exist, and never miss one that does."),
    s(4, "How would you design fulfilment-centre selection for a multi-item order?", "Treat it as an optimisation. Find nodes with reserved or reservable stock for each item. Generate candidate plans, single node or split, and filter to those that meet the promise date given cutoffs and capacity. Then pick the lowest total cost, which includes picking, packaging, linehaul, last-mile and the cost of an extra box. Splits are allowed when they are the only way to keep the promise or are clearly cheaper. An exact solve is expensive, so I would use heuristics: prefer the node that covers the most items, and prune distant nodes. I would cap computation time and fall back to a good-enough plan. The plan can be re-run before release to the floor if stock or capacity changed."),
    s(4, "Sketch the core data model for orders through delivery.", "Order holds order ID, customer ID, idempotency key, status, address snapshot, promise date and totals. OrderLine holds order ID, line ID, SKU, quantity, price and offer snapshot. Payment holds order ID, method, authorisation reference, status and hold expiry. A Capture table links payment and shipment with an amount and status. Reservation holds SKU, node, quantity, order line and expiry. Shipment holds shipment ID, order ID, node, carrier, tracking ID, status and promised date. ShipmentLine maps order lines to shipments. ScanEvent is append-only, keyed by tracking ID, with type, location, device timestamp and received time. Prices and addresses are snapshotted so later catalogue edits never change a placed order."),
    s(4, "How would you do capacity estimates for a festival sale peak without real numbers?", "I would state assumptions explicitly and derive from them. Start with expected peak orders per second, as a multiple of a normal day's average. Multiply by fan-out: each order generates several reads to price and promise, one authorisation, several inventory writes, and several events. Checkout reads are typically far higher than order writes, because many people browse and check promises without buying. Size the inventory store for the worst hot SKU, not the average, because contention is what breaks. Size the event stream by events per second and retention. Size tracking by parcels multiplied by scans per parcel. Then add headroom, load test at that level beforehand, and pre-scale, because autoscaling reacts too slowly to a sale that starts at a fixed minute."),
    s(3, "How does pay-on-delivery change the workflow on amazon.in?", "There is no authorisation, so the order is created with payment pending collection, and the stock is reserved without any funds held. The risk shifts to refusal at the doorstep, which becomes a return-to-origin parcel and costs two-way logistics. Controls include eligibility rules by pincode, order value and customer history, and limits on open pay-on-delivery orders. The driver app records cash or digital collection at the door, and that becomes the payment event. It must still be idempotent, because the app may resend offline. Cash collected by drivers must be reconciled with delivery station deposits. Refused parcels release their reservation back to inventory only after they are received and graded at the node."),
    s(3, "UPI payments can stay pending. How do you handle that state?", "UPI confirmation can arrive asynchronously, after the customer approves in their app. I model payment states explicitly: initiated, pending, success, failed. The order is created in a pending-payment state with stock reserved for a short window. Success arrives through the gateway callback or a status poll using the same transaction reference. Both paths go through one idempotent handler, so the order moves to confirmed exactly once. If the window expires without success, the reservation is released and the order is cancelled. If money later shows as debited, reconciliation triggers an automatic refund. The customer screen must say pending clearly, so they do not pay twice."),
    s(4, "After reservation, the FC finds the unit is damaged. What happens?", "The pick fails with a reason code, and the node marks that unit unsellable, which corrects inventory. The order line goes back to fulfilment selection, which looks for another node that can still meet the promise date, even at higher cost. Paying more to keep the promise is usually the right trade. If no node can meet the date, the system picks the best alternative, updates the promise, and notifies the customer proactively with the option to cancel. Payment is unaffected until ship, because capture follows the ship event. Metrics on pick failures by node feed the weekly review, because frequent phantom inventory means cycle counts or receiving processes need fixing."),
    s(4, "Design the package tracking system.", "Scanners, sort systems and driver apps emit scan events to an ingestion API. The API validates the device, attaches received time and writes to a durable stream partitioned by tracking ID, so events for one parcel stay ordered in processing. A tracking processor applies events to a per-parcel state machine and updates a read-optimised tracking view, a key-value record per tracking ID that the customer page and notifications read. This is a CQRS split: the write side is an append-only event log, and the read side is a cheap lookup. Notifications fire on meaningful transitions such as shipped, out for delivery and delivered, with dedup. The raw events are kept for audit, disputes and analytics."),
    s(3, "Scan events arrive late or out of order. How do you keep tracking correct?", "Driver apps work offline and batch uploads, so order of arrival is not order of occurrence. Each event carries a device timestamp and a per-device sequence number, and is deduplicated by event ID. The state machine only allows forward transitions in its lifecycle, so a late 'out for delivery' event cannot overwrite 'delivered'. It is still stored in the history and shown in the timeline by event time. Clock skew on devices is handled by using the sequence number within a device and server receive time as a tiebreak. Exceptions such as damage or delivery attempted are allowed to move the state sideways, and conflicts are flagged for review rather than silently resolved."),
    s(3, "How do you handle proof of delivery and driver location data responsibly?", "Proof of delivery may include a delivery code, a photo or a geotag. That data is personal, so I collect only what is needed for the dispute window, encrypt it, restrict access by role, and delete it on a defined retention schedule. Live driver location is shown to the customer only near their stop and only while the parcel is out for delivery, not as a full route. Customer phone numbers should be masked through call bridging, so drivers never see raw numbers. In India, this also needs to align with the Digital Personal Data Protection Act's obligations around purpose limitation and consent. Every access to proof-of-delivery photos is logged."),
    s(3, "Address validation in India is messy. How would you approach it at checkout?", "Start with pincode serviceability, because it decides whether a promise is even possible and which delivery station owns the address. Then normalise free text: house, street, locality, landmark. Match it against known delivered addresses and geocodes to suggest corrections, while accepting landmarks because many addresses rely on them. Ask for a pin drop on the map where geocoding confidence is low. I would not block checkout on low confidence. I would flag it so the delivery station can call ahead. Feedback from failed attempts, such as 'address not found', updates the address quality score, so the next order to that address gets a better prompt."),
    s(4, "Why might a shopping cart prefer availability over strong consistency?", "Amazon's 2007 Dynamo paper describes exactly this. Being unable to add to the cart loses sales and frustrates customers, so the cart should always accept writes even during partitions. If replicas diverge, the system keeps both versions and merges them, typically as a union of items. The known cost is that a deleted item can occasionally reappear. That is acceptable because the cart is not the source of truth for money or stock. Checkout is where you switch to strong guarantees: the price is recomputed, inventory is reserved with conditional writes, and payment is idempotent. Choosing consistency per step, not per system, is the key point to make in an interview."),
    s(4, "Would you use a distributed transaction or a saga for the order flow?", "A saga. The flow spans services owned by different teams: payment, order, inventory, fulfilment and shipping. These are separated by APIs and run for hours or days, so holding locks across them with two-phase commit is impractical and couples availability. Each step is a local transaction that emits an event. Each step has a compensating action: void the authorisation, release the reservation, cancel the shipment. I would use orchestration for the core order lifecycle, so one service owns the state machine and timeouts and the status is easy to answer. Choreography fits peripheral consumers such as notifications. Every step and compensation must be idempotent, because retries are normal."),
    s(4, "A customer cancels just as the parcel is being shipped. How do you resolve the race?", "The order line has one state machine, and transitions use conditional writes. Cancellation succeeds only if the state is still before 'shipped'. The ship confirm also succeeds only if the line is not cancelled. Whichever write lands first wins. If cancel wins, the warehouse system gets a stop signal, the parcel is pulled before the truck, the reservation is released and the authorisation is voided, so no capture happens. If ship wins, the customer is told it has already shipped and offered refuse-on-delivery or a return, and the capture proceeds normally. The important thing is never to allow both cancel-confirmed and capture."),
    s(3, "How do you handle reservations for orders that are never completed?", "Every reservation has an owner and an expiry. For confirmed orders, the reservation lives until pick. For pending payment, such as a UPI or 3-D Secure flow, it gets a short time-to-live. A sweeper, or a TTL on the reservation record plus an expiry event, releases stock when the window passes without confirmation. Release must be idempotent and conditional on the reservation still being unconsumed, so it never frees a unit that was already picked. I would measure the reserved-but-unconverted ratio, because a TTL that is too long hides sellable stock during a sale, while one that is too short cancels customers who are mid-payment."),
    s(4, "Why does Amazon use six-page narratives instead of slides?", "Amazon has publicly explained that full sentences force clearer thinking than bullet points, because a narrative has to connect claims, reasons and trade-offs. Slides let gaps hide behind formatting and the presenter's delivery. The meeting starts with everyone reading the document silently, so everyone actually has the same context. Discussion then focuses on the hard questions rather than on a presentation. As an engineer, I would write a design doc that way: the customer problem, the tenets, options considered, the proposal, risks and open questions. The appendix holds the data. The cost is writing time, but it is cheaper than a misaligned decision."),
    s(4, "What are the trade-offs of two-pizza teams that communicate only through APIs?", "The benefits are autonomy and speed. A small team owns a service end to end, can deploy independently, and has a clear owner for every alarm. API-only access, from the well-known early-2000s mandate, stops hidden coupling through shared databases, so teams can change internals freely. The costs are duplication, coordination overhead for cross-cutting changes, and many dependencies that each can fail. A checkout call may fan out to dozens of services. That pushes you toward strong API contracts, versioning, timeouts, fallbacks and dependency dashboards. Someone also has to own the end-to-end experience, such as the delivery promise, even though no single team owns every piece."),
    s(4, "Give examples of controllable input metrics for this pipeline that a weekly business review would inspect.", "Output metrics like revenue or order count are results; the team cannot directly move them. Inputs it can move include in-stock rate for top items and promise accuracy, meaning the share of orders delivered by the promised date. Others are click-to-ship time at each node, pick failure rate, mis-sort rate at sortation, first-attempt delivery success by delivery station, checkout latency at the 99th percentile, payment authorisation success by method, and the double-charge or reconciliation exception count. A good review looks at week-over-week trends and anomalies, asks owners to explain variance, and turns findings into actions. It should also check that each metric's definition is still measuring what we think."),
    s(4, "What goes into a Correction of Error document, and what makes one good?", "A COE covers the customer impact with data, a timeline, and the detection and response. It asks repeated 'why' questions to reach the root causes, lessons learned, and concrete action items with owners and dates. A good one is blameless: it assumes people acted reasonably given the information they had, and asks why the system let the mistake happen. It also asks why detection was not faster and why the blast radius was that large. Good action items are mechanisms, such as automated checks, alarms or deployment safeguards, rather than 'be more careful'. For example, a double-charge incident should end with an idempotency test in the pipeline, not a reminder email."),
    s(3, "Tell me about a time you worked backwards from the customer.", "I use a STAR structure. For example: our team was asked to build a bulk order export. Instead of starting with the database, I wrote a one-page customer-facing announcement and FAQ and showed it to three account managers. Their questions showed that customers did not want exports at all. They wanted a weekly reconciliation of discrepancies. We changed the scope to an exceptions report, which was smaller to build. Adoption was strong, and support tickets on that topic fell noticeably. The lesson I took was that writing the customer announcement first is the fastest way to discover you are solving the wrong problem. I would quantify results with real numbers from my own experience."),
    s(3, "How would you draft a PR/FAQ for same-day delivery in smaller Indian cities?", "The press release names the customer and the benefit in plain words. For example: shoppers in a listed city can get eligible items the same day if ordered before a cutoff. It says why that matters to them and includes a customer quote. The external FAQ answers which items qualify, the cost, and what happens if the parcel is late. The internal FAQ covers the hard parts: which nodes hold the right selection, last-mile capacity and driver supply, how the promise service avoids overpromising, unit economics, and the risks. If the internal FAQ cannot answer whether we can keep the promise reliably, the project should not start yet."),
    s(3, "Your checkout depends on another team's service, and it gets slow during peak. What do you do?", "In the moment, I protect checkout. I use tight timeouts, a circuit breaker, and a fallback where one is safe. For a non-critical call like recommendations, I skip it. For a critical one like the promise, I might use a cached, more conservative estimate rather than fail. Afterwards, I raise it through the owning team's channels with data such as latency charts and call volumes, because they own the fix. Together we agree on an SLA, load-test jointly before the next sale, and consider pre-scaling or caching. If it caused customer impact, it gets a COE. I would not reach into their database or fork their logic; the API is the contract."),
    s(4, "How do you handle card data securely in this pipeline, especially in India?", "Card numbers should never touch most of our services. The checkout page collects card data in a PCI DSS scoped component or via the gateway's hosted fields, and the rest of the system sees only a token. Under RBI card-on-file tokenisation rules, merchants in India cannot store full card numbers for saved cards and must use network or issuer tokens instead. Logs and events must exclude card data and CVV entirely, and should mask other personal data. Payment service access uses least privilege and short-lived credentials, keys live in a managed key service, and the order events carry payment references, not instruments."),
    s(4, "The payment service is partially down during checkout. How should the system degrade?", "Never fake success on payment, because that breaks money guarantees. I would route around failure by method: if one gateway or the card path is failing, keep UPI or other healthy methods available and tell the customer clearly. Use retries with the same idempotency key and backoff, and use circuit breakers so a failing dependency does not exhaust threads. Option to accept the order with payment pending and authorise asynchronously is a business decision: it raises fraud and failed-payment risk, so I would only allow it for low-risk customers and amounts. Everything upstream, like the cart and browsing, should keep working, because it does not need payment."),
    s(3, "What alarms would you put on this order pipeline?", "I would put alarms on customer-facing symptoms first. These include checkout error rate and latency, authorisation success rate per method, and order creation rate compared with the same time last week, because a drop often signals a silent failure. Then workflow health: orders stuck in one state past a threshold, outbox relay lag, consumer lag on order events, and reservation failures. For money, I would alarm on capture count per shipment greater than one and reconciliation mismatches. For delivery, I would watch parcels with no scan for too long and promise-at-risk counts by station. Each alarm needs an owner, a runbook and a severity, and should page only when it needs human action now."),
    s(3, "How would you limit the blast radius of a bad deployment in this system?", "Use cell-based architecture: split customers or regions into independent cells, each with its own stack, so one bad cell affects a fraction of traffic. Amazon has written publicly about cells and shuffle sharding for this reason. Deployments roll out gradually, one box, then one zone, then one region, with automated rollback on alarm, and bake time between waves. Feature flags separate deploy from release. Business code freezes before major sales reduce risk when stakes are highest. For data changes such as schema migrations, use expand-and-contract, so old and new code both work during the rollout and rollback stays possible."),
  ],
  objective: [
    o(5, "Which pattern reliably saves an order and publishes its order-created event without a distributed transaction?", ["Write to the database, then publish in a finally block","Transactional outbox with a relay or change data capture","Two-phase commit between the database and the broker","Publish first, then write to the database"], 1, "The outbox row commits atomically with the order, and a relay publishes it at least once, so neither the order nor its event is lost."),
    o(5, "What is the safest way to prevent overselling the last unit under concurrent checkouts?", ["Read available stock, then write the new value","Cache stock in each checkout server","An atomic conditional decrement that succeeds only if enough stock remains","Check stock again after payment capture"], 2, "A conditional write lets exactly one concurrent request win, while read-then-write races and lets both succeed."),
    o(4, "At the start of an Amazon six-pager meeting, attendees typically…", ["Watch the author present slides","Read the document silently","Vote on the proposal","Review the code diff"], 1, "Amazon has publicly described starting meetings with silent reading, so everyone shares the same context before discussion."),
    o(4, "The 'two-pizza team' idea mainly describes…", ["A team small enough to be fed by two pizzas","A team that has two managers","Two teams sharing one service","A team rotating on-call every two weeks"], 0, "It is a size heuristic: teams small enough to stay fast and own a service end to end."),
    o(4, "In Amazon's operating vocabulary, COE stands for…", ["Centre of Excellence","Cost of Engineering","Correction of Error","Chain of Escalation"], 2, "A Correction of Error is Amazon's post-incident analysis with root causes and action items."),
    o(4, "Which is a controllable input metric rather than an output metric for a fulfilment team?", ["Quarterly revenue","Share price","Total profit","Percentage of orders delivered by the promised date"], 3, "Promise accuracy is something the team can directly act on, whereas revenue and profit are outcomes."),
    o(5, "A client retries order creation with the same idempotency key after a timeout. The server should…", ["Create a second order","Return the result of the original request","Reject it with a conflict error","Cancel the first order and create a new one"], 1, "Idempotency means the same key returns the same outcome, so retries never create duplicate orders or charges."),
    o(3, "To keep all events for one order in sequence on a partitioned stream, you should…", ["Use a random partition key","Use the order ID as the partition key","Use a single partition for all traffic","Use the timestamp as the key"], 1, "Streams typically guarantee order within a partition, and keying by order ID keeps one order's events together while still scaling across partitions."),
    o(4, "An order splits into two shipments that ship on different days. With charge-on-ship, payment is…", ["Captured in full when the first shipment ships","Captured only after both are delivered","Captured per shipment as each one ships","Captured at checkout"], 2, "Each ship event triggers a capture for that shipment's amount, matching the practice of charging when items ship."),
    o(3, "Amazon's 2007 Dynamo paper describes a shopping cart that…", ["Uses strong consistency and rejects writes during partitions","Stays writable and reconciles divergent versions","Stores carts only in the browser","Locks the cart during checkout"], 1, "Dynamo prioritised availability for the cart and merged conflicting versions, accepting that deleted items could occasionally reappear."),
    o(4, "Under RBI card-on-file tokenisation rules, an Indian merchant saving a card for repeat purchases should…", ["Store the full card number encrypted","Store the card number and CVV","Store a network or issuer token instead of the card number","Ask the customer to email card details"], 2, "RBI rules prevent merchants from storing actual card data for saved cards, so tokens are used instead."),
    o(3, "A UPI payment shows pending after the customer approves. The correct handling is…", ["Mark it failed and ask the customer to pay again","Keep it pending and confirm through callback or status check under the same reference","Create a second payment request","Ship the order immediately"], 1, "Pending is an unknown outcome, and reconciling under the same reference avoids duplicate debits."),
    o(4, "Event consumers in the order pipeline receive messages at least once. Therefore they must be…", ["Idempotent","Single-threaded","Stateless with no database","Synchronous"], 0, "Redelivery is expected with at-least-once delivery, so processing the same event twice must have the same effect as once."),
    o(3, "A late 'out for delivery' scan arrives after 'delivered'. The tracking state should…", ["Move back to out for delivery","Delete the delivered event","Stay delivered and record the late scan in history","Reset the parcel to in transit"], 2, "A forward-only state machine prevents late events regressing state, while history still keeps every scan."),
    o(4, "The goal of fulfilment-centre selection in this workflow is to…", ["Always use the nearest node","Always ship from a single node","Meet the promise date at the lowest total cost","Choose the node with the most stock"], 2, "The promise is a constraint, and among feasible plans the lowest total cost, including any split, wins."),
    o(4, "The widely reported early-2000s API mandate at Amazon required teams to…", ["Share one central database","Communicate only through service interfaces","Write all code in one language","Release on a single shared schedule"], 1, "Teams had to expose data and functions only through service interfaces, with no direct database access between them."),
    o(4, "Payment is authorised, but inventory reservation then fails for every node. In a saga, the compensating step is to…", ["Capture the payment and refund later","Void or reverse the authorisation","Keep the hold until the customer complains","Retry reservation forever"], 1, "Compensation undoes completed steps, so the hold is released without ever charging the customer."),
    o(3, "A shipment is delayed beyond the authorisation hold's validity. Before capture you should…", ["Capture anyway","Cancel the order automatically","Re-authorise, then capture","Switch the order to pay-on-delivery"], 2, "Expired holds may not be capturable, so a fresh authorisation is needed before charging at ship time."),
    o(4, "In working backwards, the PR/FAQ is written…", ["After launch for marketing","Before building, from the customer's point of view","Only for AWS products","By the legal team"], 1, "The press release and FAQ define the customer value and hard questions before engineering begins."),
    o(3, "A key operational risk specific to pay-on-delivery is…", ["Card chargebacks","Authorisation hold expiry","Refusal at the door causing return-to-origin costs","3-D Secure failures"], 2, "With no prepayment, customers can refuse the parcel, creating two-way logistics cost and inventory delay."),
    o(3, "Cell-based architecture mainly helps by…", ["Reducing code size","Limiting the blast radius of failures to a subset of customers","Removing the need for monitoring","Guaranteeing zero latency"], 1, "Independent cells mean a bad deployment or fault affects only the traffic routed to that cell."),
    o(4, "Which step most needs strong consistency?", ["Product recommendations","Inventory reservation","Showing review counts","Browsing history"], 1, "Reservation decides whether a unit is sold, so stale reads there cause overselling, while the others tolerate eventual consistency."),
    o(4, "The delivery promise at checkout is best computed from…", ["A fixed number of days for every pincode","Inventory location and network capacity including cutoffs","The customer's order history only","The seller's preference"], 1, "A promise is only honest if it reflects where stock is and whether processing, transit and last-mile capacity exist."),
    o(3, "A hot SKU during a flash sale causes write contention on one inventory row. A common fix is to…", ["Disable reservation for that SKU","Split its stock into several buckets on different partitions","Increase the cache TTL","Allow negative stock"], 1, "Spreading quantity across buckets spreads writes, and each bucket still uses conditional decrements so stock never goes negative."),
    o(4, "A cancel and a ship-confirm arrive at the same moment. The correct design is…", ["Process both and refund later","Conditional state transitions so only one can win","Always prefer the ship event","Lock the whole order table"], 1, "Conditional writes on the order line state ensure the system never confirms a cancellation and also captures payment."),
    o(3, "For proof-of-delivery photos, a privacy-respecting design should…", ["Keep them forever for analytics","Make them public with the tracking link","Restrict access, log views and delete after a retention period","Email them to the driver"], 2, "Purpose limitation and least access reduce exposure of personal data while still supporting disputes."),
    o(3, "Amazon's narrative memos are meant to replace…", ["Code reviews","Slide decks with bullet points","On-call rotations","Unit tests"], 1, "Amazon has publicly said narratives force clearer reasoning than slide-based presentations."),
    o(3, "A weekly business review is most useful when it…", ["Celebrates monthly revenue only","Inspects controllable inputs, trends and anomalies with owners","Reviews every line of code","Replaces incident reviews"], 1, "WBRs focus on metrics teams can act on and on explaining variances, which drives what to fix next."),
    o(3, "To absorb a sudden burst of ship events without overloading the payment service, you should…", ["Call payment synchronously from every scanner","Queue capture requests and process them at a controlled rate","Drop excess events","Capture at checkout instead"], 1, "Queue-based load levelling smooths bursts, and idempotent captures make retries from the queue safe."),
    o(3, "Serving the customer tracking page cheaply at scale is best done by…", ["Scanning all raw scan events on each request","A precomputed per-parcel tracking view separate from the event log","Querying the warehouse system directly","Asking the driver app for status"], 1, "A CQRS read model turns each page view into a single key lookup, while the event log stays the source of truth."),
  ],
};
export default bank;
